# area: constructors_metaclasses
# hypothesis: a metaclass __call__ that returns object should make Shape() infer as object in mypy and ty, while type[T]() on the same class keeps the T that was passed in.
from typing import TypeVar, reveal_type

T = TypeVar('T')


class Registry(type):
    def __call__(cls, *args: object, **kwargs: object) -> object:
        return super().__call__(*args, **kwargs)


class Shape(metaclass=Registry):
    def __new__(cls, sides: int = 0) -> 'Shape':
        return super().__new__(cls)

    def __init__(self, sides: int = 0) -> None:
        self.sides = sides


class Square(Shape):
    side_hint: int = 4


def build(kind: type[T]) -> T:
    return kind()


reveal_type(Shape())
reveal_type(Square())
reveal_type(build(Square))
reveal_type(build(Shape))
